SELECT conversation_id, argMax(trace_id, end_ts) AS trace_id, argMax(user_id, end_ts) AS user_id, argMax(source, end_ts) AS source, argMax(agent_id, end_ts) AS agent_id, argMax(agent_name, end_ts) AS agent_name, argMax(start_ts, end_ts) AS start_ts, max(end_ts) AS end_ts, argMax(duration_ms, end_ts) AS duration_ms, argMax(status, end_ts) AS status, argMax(error_message, end_ts) AS error_message, argMax(event_count, end_ts) AS event_count, argMax(token_input, end_ts) AS token_input, argMax(token_output, end_ts) AS token_output, argMax(model, end_ts) AS model FROM trace_conversation
AND source = #{source}
GROUP BY conversation_id ORDER BY max(end_ts) DESC LIMIT #{offset}, #{limit}

SELECT count(DISTINCT conversation_id)
FROM trace_conversation


        AND source = #{source}

SELECT event_json
FROM trace_event
WHERE conversation_id = #{conversationId}
  AND trace_id = #{traceId}
ORDER BY timestamp ASC
